<?php defined('BASEPATH') OR exit('No direct script access allowed');
class Attachments extends MY_Controller {
 private $c; public function __construct(){parent::__construct();$this->c=$this->require_auth();if(!$this->c)return;$this->load->model('Attachment_model','attachments');}
 public function index(){if($this->input->method(TRUE)==='POST')return $this->upload();$page=max(1,(int)$this->input->get('page'));$per=min(100,max(1,(int)($this->input->get('perPage')?:25)));return $this->respond($this->attachments->listing($this->c['organizationId'],trim((string)$this->input->get('q')),$page,$per));}
 private function upload(){if(empty($_FILES['file'])||$_FILES['file']['error']!==UPLOAD_ERR_OK)return $this->fail('BAD_REQUEST','file required or upload failed',400);$f=$_FILES['file'];if(!$f['size']||$f['size']>25*1024*1024)return $this->fail('VALIDATION_ERROR','File must contain data and not exceed 25MB',422);$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$allowed=array('text/plain','text/markdown','text/csv','application/pdf','application/json','image/png','image/jpeg','image/gif','image/webp','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document');if(!in_array($mime,$allowed,TRUE))return $this->fail('VALIDATION_ERROR','File type '.$mime.' not allowed',422);$cid=$this->input->post('conversationId');if(!$this->attachments->target_ok($cid,$this->c['organizationId']))return $this->fail('NOT_FOUND','Conversation not found',404);if($this->input->post('talkMessageId'))return $this->fail('VALIDATION_ERROR','Talk message attachments require the Talk module',422);list($r,$e)=$this->attachments->create($this->c['organizationId'],$this->c['sub'],$f,$cid);return $r?$this->respond($r,201):$this->fail('UPLOAD_FAILED','Attachment storage failed: '.$e,500);}
 public function item($id){$r=$this->attachments->one($id,$this->c['organizationId']);if(!$r)return $this->fail('NOT_FOUND','Attachment not found',404);if($this->input->method(TRUE)==='DELETE'){$e=$this->attachments->remove($id,$this->c['organizationId'],$this->c['sub']);if(!$e){$this->output->set_status_header(204)->set_output('');return;}return $this->fail($e==='forbidden'?'FORBIDDEN':'VALIDATION_ERROR',$e==='forbidden'?'Only the uploader can delete this attachment':'Attached files cannot be deleted; remove the message instead',$e==='forbidden'?403:400);}$path=APPPATH.'storage/uploads/'.$r['storage_key'];if(!is_file($path))return $this->fail('NOT_FOUND','Attachment file not found',404);$this->output->set_content_type($r['mime_type'])->set_header('Content-Length: '.filesize($path))->set_header("Content-Disposition: inline; filename*=UTF-8''".rawurlencode($r['filename']))->set_output(file_get_contents($path));}
 public function metadata($id){$r=$this->attachments->one($id,$this->c['organizationId']);return $r?$this->respond($this->attachments->view($r)):$this->fail('NOT_FOUND','Attachment not found',404);}
}
